Q: WebView can&#39;t showing login js pupup &quot;basic auth&quot; in react-native A: <p>As of</p>
<pre><code>&quot;react-native-webview&quot;: &quot;^13.15.0&quot;
</code></pre>
<p>use;</p>
<pre><code>import { SafeAreaView, StyleSheet } from 'react-native';
import WebView from 'react-native-webview';

const username = 'user';
const password = 'pass';

export default function App() {
  return (
    &lt;SafeAreaView style={styles.container}&gt;
      &lt;WebView
        source={{
          uri: `https://authenticationtest.com/HTTPAuth/`,
        }}
        basicAuthCredential={{
          username: username,
          password: password,
        }}
      /&gt;
    &lt;/SafeAreaView&gt;
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
});
</code></pre>
